function olayPenceresi(): void { const g = G; if (!g || ekr !== 'ana' || macRapor || !g.bekleyenOlay || document.querySelector('.modal.olay, .macekr, .mg')) return; const o = olayOf(g.bekleyenOlay), dlg = document.createElement('div'); dlg.className = 'modal olay'; dlg.innerHTML = `<div><div class="pill y">${o.ik} Karar zamanı</div><h3 style="margin:0">${esc(o.baslik)}</h3><div class="news" style="font-size:13px">${esc(o.metin(g))}</div>${o.secenekler.map((s, i) => { const yok = s.kosul && !s.kosul(g); return `<button class="btn ${i ? 'sec' : ''}" data-o="${i}" ${yok ? 'disabled' : ''} style="text-align:left">${esc(s.ad)}${s.ac ? `<br><small style="font-weight:500">${esc(s.ac)}</small>` : ''}</button>`; }).join('')}</div>`; document.body.appendChild(dlg); dlg.onclick = (e) => { const b = (e.target as HTMLElement).closest<HTMLElement>('[data-o]'); if (!b || !G) return; const r = olayCoz(G, +b.dataset.o!); dlg.remove(); toast(r.ok ? `${r.m}${r.ozet.length ? ' · ' + r.ozet.slice(0, 3).join(', ') : ''}` : r.m, !r.ok); saveNow(); render(); }; }
function render(): void { temaUygula(); const y = app.querySelector('main')?.scrollTop ?? 0; app.innerHTML = ekr === 'baslik' ? baslik() : ekr === 'olustur' ? olustur() : G ? ana(G) : baslik(); const m = app.querySelector('main'); const an = `${ekr}|${nav}|${sekme}|${ligSec}`; if (m) { m.scrollTop = an === sonAnahtar ? y : 0; if (an !== sonAnahtar) m.classList.add('gecis'); } sonAnahtar = an; olayPenceresi(); }
